import { test, expect } from '@playwright/test';

test.describe('Debounced Search Functionality', () => {
  let requestCount = 0;

  test.beforeEach(async ({ page }) => {
    requestCount = 0;

    // Mock the search API endpoint
    await page.route('**/api/search**', async (route) => {
      requestCount++;
      await route.abort();
    });

    // Navigate to the search page
    await page.goto('data:text/html,<html><body><input id="search-input" type="text" placeholder="Search..." /><div id="results"></div><script>
      let debounceTimer;
      const searchInput = document.getElementById("search-input");
      const resultsDiv = document.getElementById("results");

      searchInput.addEventListener("input", (e) => {
        clearTimeout(debounceTimer);
        debounceTimer = setTimeout(() => {
          const query = e.target.value;
          if (query.trim()) {
            fetch(`/api/search?q=${encodeURIComponent(query)}`)
              .then(r => r.json())
              .then(data => {
                resultsDiv.innerHTML = `<div class="search-result">Results for: ${query}</div>`;
              })
              .catch(() => {
                resultsDiv.innerHTML = `<div class="search-result">Search attempted for: ${query}</div>`;
              });
          }
        }, 300);
      });
    </script></body></html>');
  });

  test('should not trigger search while user is typing', async ({ page }) => {
    const searchInput = page.getByRole('textbox', { name: /search/i });

    // Type characters with delays less than 300ms
    await searchInput.click();
    await searchInput.type('t', { delay: 50 });
    await page.waitForTimeout(100);
    expect(requestCount).toBe(0);

    await searchInput.type('e', { delay: 50 });
    await page.waitForTimeout(100);
    expect(requestCount).toBe(0);

    await searchInput.type('s', { delay: 50 });
    await page.waitForTimeout(100);
    expect(requestCount).toBe(0);

    await searchInput.type('t', { delay: 50 });
    await page.waitForTimeout(100);
    expect(requestCount).toBe(0);
  });

  test('should trigger search after 300ms of inactivity', async ({ page }) => {
    const searchInput = page.getByRole('textbox', { name: /search/i });

    // Type a character
    await searchInput.click();
    await searchInput.type('p', { delay: 50 });

    // Wait less than 300ms - should not trigger
    await page.waitForTimeout(200);
    expect(requestCount).toBe(0);

    // Wait for the remaining time to reach 300ms total
    await page.waitForTimeout(150);

    // Now the search should have been triggered
    expect(requestCount).toBe(1);
  });

  test('should reset debounce timer on each keystroke', async ({ page }) => {
    const searchInput = page.getByRole('textbox', { name: /search/i });

    // Type first character
    await searchInput.click();
    await searchInput.type('s', { delay: 50 });

    // Wait 250ms (less than 300ms debounce)
    await page.waitForTimeout(250);
    expect(requestCount).toBe(0);

    // Type another character - this should reset the timer
    await searchInput.type('e', { delay: 50 });

    // Wait another 250ms (total 500ms from first char, but only 250ms from second)
    await page.waitForTimeout(250);
    expect(requestCount).toBe(0);

    // Wait for the remaining debounce time from the second character
    await page.waitForTimeout(100);

    // Now search should trigger (300ms after the last keystroke)
    expect(requestCount).toBe(1);
  });

  test('should trigger multiple searches for different queries with proper debouncing', async ({ page }) => {
    const searchInput = page.getByRole('textbox', { name: /search/i });

    // First search query
    await searchInput.click();
    await searchInput.type('query1', { delay: 50 });

    // Wait for debounce to complete
    await page.waitForTimeout(350);
    expect(requestCount).toBe(1);

    // Clear and type second query
    await searchInput.clear();
    await searchInput.type('query2', { delay: 50 });

    // Wait for debounce to complete
    await page.waitForTimeout(350);
    expect(requestCount).toBe(2);
  });

  test('should handle rapid typing followed by pause correctly', async ({ page }) => {
    const searchInput = page.getByRole('textbox', { name: /search/i });

    // Rapid typing with very small delays
    await searchInput.click();
    await searchInput.type('automation', { delay: 20 });

    // Should not have triggered yet
    expect(requestCount).toBe(0);

    // Wait for debounce
    await page.waitForTimeout(350);

    // Should trigger exactly once
    expect(requestCount).toBe(1);
  });

  test('should cancel previous search request when new input arrives before debounce completes', async ({ page }) => {
    const searchInput = page.getByRole('textbox', { name: /search/i });

    // Type first character
    await searchInput.click();
    await searchInput.type('a', { delay: 50 });

    // Wait 200ms (less than 300ms)
    await page.waitForTimeout(200);

    // Type more characters before debounce completes
    await searchInput.type('b', { delay: 50 });
    await searchInput.type('c', { delay: 50 });

    // Wait for debounce from the last character
    await page.waitForTimeout(350);

    // Should only have one request (the previous one was cancelled)
    expect(requestCount).toBe(1);
  });
});
